using System;// A type that represents a 2-D point.public struct Point{    private int x;    private int y;    public Point(int x, int y)    {       this.x = x;       this.y = y;    }    public override bool Equals(Object obj)    {       if (! (obj is Point)) return false;       Point p = (Point) obj;       return x == p.x & y == p.y;    }    public override int GetHashCode()    {        return x ^ y;    }}public class Example{   public static void Main()   {      Point pt = new Point(5, 8);      Console.WriteLine(pt.GetHashCode());      pt = new Point(8, 5);      Console.WriteLine(pt.GetHashCode());   }}// OR    public struct HSLColor {        public override bool Equals(object o) {            return Equals((HSLColor)o);        }        // added by MerlinEl 2022        public bool Equals(HSLColor right) {            return (                Hue == right.Hue &&                Lightness == right.Lightness &&                Saturation == right.Saturation            );        }        // added by MerlinEl 2022        public override int GetHashCode() => ToRGB().GetHashCode();        public static bool operator !=(HSLColor left, HSLColor right) {            return !(left == right);        }        public static bool operator ==(HSLColor left, HSLColor right) {            return (left.Hue == right.Hue &&                    left.Lightness == right.Lightness &&                    left.Saturation == right.Saturation);        }        public override string ToString() {            string s = string.Format("HSL({0:f2}, {1:f2}, {2:f2})", Hue, Saturation, Lightness);            return s;        }